--
-- Name: v_emails_activity; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_emails_activity AS
 SELECT type,
    count(*) AS total,
    count(*) FILTER (WHERE ((status)::text = 'sent'::text)) AS envoyes,
    count(*) FILTER (WHERE ((status)::text = 'failed'::text)) AS echoues
   FROM public.emails_log
  WHERE (sent_at >= (now() - '30 days'::interval))
  GROUP BY type;


--
-- Name: v_merchant_dashboard; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_merchant_dashboard AS
 SELECT mt.processing_id,
    mt.raison_sociale,
    mt.terminal_id,
    mt.bank_name,
    mt.statut,
    mt.date_import,
    mt.date_prise_en_charge,
    mt.date_validation,
    mt.date_production,
    (EXTRACT(day FROM (now() - mt.date_import)))::integer AS jours_depuis_import,
    u1.email AS operateur_pec,
    u2.email AS operateur_validation,
        CASE mt.statut
            WHEN 'en_attente'::text THEN 1
            WHEN 'prise_en_charge'::text THEN 2
            WHEN 'recettes_envoyees'::text THEN 3
            WHEN 'recettes_recues'::text THEN 4
            WHEN 'valide'::text THEN 5
            WHEN 'banque_notifiee'::text THEN 6
            WHEN 'en_production'::text THEN 7
            ELSE 0
        END AS etape_num
   FROM ((public.merchants_tracking mt
     LEFT JOIN public.users u1 ON ((mt.operateur_prise_en_charge = u1.id)))
     LEFT JOIN public.users u2 ON ((mt.operateur_validation = u2.id)))
  ORDER BY mt.date_import DESC;


