--

CREATE TABLE public.validations (
    id uuid DEFAULT public.uuid_generate_v4() NOT NULL,
    processing_id character varying(20) NOT NULL,
    raison_sociale character varying(255),
    terminal_id character varying(20),
    email_marchand character varying(255),
    filename character varying(255) NOT NULL,
    verdict character varying(20) DEFAULT 'pending'::character varying NOT NULL,
    total_cas integer DEFAULT 0 NOT NULL,
    cas_reussis integer DEFAULT 0 NOT NULL,
    cas_echoues integer DEFAULT 0 NOT NULL,
    cas_en_attente integer DEFAULT 0 NOT NULL,
    critiques_reussis integer DEFAULT 0 NOT NULL,
    taux_reussite numeric(5,2) DEFAULT 0,
    cases_json jsonb,
    anomalies_json jsonb,
    marchand_notifie_at timestamp with time zone,
    banque_notifiee_at timestamp with time zone,
    banque_notifiee_nom character varying(100),
    banque_notifiee_email character varying(255),
    prod_email_envoye_at timestamp with time zone,
    valide_par uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT validations_verdict_check CHECK (((verdict)::text = ANY ((ARRAY['approved'::character varying, 'refused'::character varying, 'pending'::character varying, 'blank'::character varying])::text[])))
);


