--
-- Name: v_validations_stats; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_validations_stats AS
 SELECT date_trunc('month'::text, created_at) AS mois,
    count(*) AS total,
    count(*) FILTER (WHERE ((verdict)::text = 'approved'::text)) AS approuves,
    count(*) FILTER (WHERE ((verdict)::text = 'refused'::text)) AS refuses,
    count(*) FILTER (WHERE ((verdict)::text = 'pending'::text)) AS incomplets,
    round(avg(taux_reussite), 1) AS taux_moyen
   FROM public.validations
  GROUP BY (date_trunc('month'::text, created_at))
  ORDER BY (date_trunc('month'::text, created_at)) DESC;


